mapper.insert:
insert into coop_settlement_cash_close (topic_id, commercial_context_type, commercial_context_id, close_kind, initiator_member_id, original_sales_basis, original_contribution_count, platform_rate, guarantee_base_rate, guarantee_step_rate, guarantee_max_merchant, original_verified_merchant_count, origin_calculation_version, contract_snapshot, source_fingerprint, closed_at)
select #{topicId}, #{commercialContextType}, #{commercialContextId}, #{closeKind}, #{initiatorMemberId}, #{originalSalesBasis}, #{originalContributionCount}, #{platformRate}, #{guaranteeBaseRate}, #{guaranteeStepRate}, #{guaranteeMaxMerchant}, #{originalVerifiedMerchantCount}, #{originCalculationVersion}, #{contractSnapshot}, #{sourceFingerprint}, #{closedAt}
from cms_topic r where r.id=#{topicId} and (r.member_id <=> #{initiatorMemberId})
  and (r.fee_platform_rate <=> #{platformRate}) and (r.fee_guarantee_base_rate <=> #{guaranteeBaseRate})
  and (r.fee_guarantee_step_rate <=> #{guaranteeStepRate}) and (r.fee_guarantee_max_merchant <=> #{guaranteeMaxMerchant})

insert into coop_settlement_cash_event (cash_close_id, event_type, source_id, source_registration_id, source_amount, source_snapshot, source_fingerprint)
select #{cashCloseId}, #{eventType}, #{sourceId}, #{sourceRegistrationId}, #{sourceAmount}, #{sourceSnapshot}, #{sourceFingerprint}
from refund_application r where r.id=#{sourceId} and binary r.source_type=binary 'registration'
  and r.source_id=#{sourceRegistrationId} and r.status=1 and r.del_flag=0
  and r.refund_amount=#{sourceAmount}
